// Pega o primeiro item retornado pelo GitHub Node
const raw = Buffer.from($input.first().json.content, 'base64').toString('utf-8');

// Converte para objeto JSON
const data = JSON.parse(raw);

const listaFilmes = Array.isArray(data) ? data : data.filmes;

return listaFilmes.map((filme, i) => ({
  json: {
    id: i + 1,
    titulo: filme.titulo,
    ano: filme.ano,
    diretor: filme.diretor,
    sinopse: filme.sinopse,
    avaliacao: filme.avaliacao,
    duracao: filme.duracao,
    idioma: filme.idioma,
    pais: filme.pais,
    elenco: filme.elenco,
    metadata: filme.metadata
  }
}));

// 1) Pega todos os itens recebidos do nó anterior (nossa lista de filmes)
let docs = $input.all().map(i => i.json);
if (Array.isArray(docs[0])) docs = docs[0]; // desembrulha se veio como array

// 2) Pequena limpeza opcional de texto
const clean = (s='') =>
  s.replace(/\u00ad/g, '')
   .replace(/[ \t]+\n/g, '\n')
   .replace(/\n{3,}/g, '\n\n');

const out = [];

// 3) Processa cada filme para criar o formato ideal para o Vector Store / Embedder
for (const filme of docs) {
  // Monta um texto descritivo rico combinando as informações do filme (ótimo para embeddings)
  const textoDescritivo = clean(`
    Título: ${filme.titulo} (${filme.ano})
    Diretor: ${filme.diretor}
    Idioma: ${filme.idioma} | Duração: ${filme.duracao} min | Avaliação: ${filme.avaliacao}
    País: ${Array.isArray(filme.pais) ? filme.pais.join(', ') : filme.pais}
    Elenco: ${Array.isArray(filme.elenco) ? filme.elenco.join(', ') : filme.elenco}
    Gêneros: ${filme.metadata?.generos ? filme.metadata.generos.join(', ') : ''}
    Temas: ${filme.metadata?.temas ? filme.metadata.temas.join(', ') : ''}
    Sinopse: ${filme.sinopse}
  `.trim());

  // Cada filme vira um item completo na base vetorial com seus metadados limpos e corretos
  out.push({
    json: {
      pageContent: textoDescritivo, // Alterado de 'context' para 'pageContent' (padrão do n8n Vector Store)
      metadata: {
        id: filme.id,
        titulo: filme.titulo,
        ano: filme.ano,
        diretor: filme.diretor,
        avaliacao: filme.avaliacao,
        idioma: filme.idioma,
        tipo: filme.metadata?.tipo || "filme",
        generos: filme.metadata?.generos || [],
        temas: filme.metadata?.temas || [],
        url_fonte: filme.metadata?.url_fonte || ""
      }
    }
  });
}

return out;
